cat > users.js <<'EOF'
class ValidationError extends Error {}

// createUser({ name, age }) returns { name, age } or throws a ValidationError.
// Rules:
//   name: a string that isn't empty after trimming.
//   age: a whole number from 0 to 150. It comes from a form, so it may be a number
//        or a numeric string like "42". The returned age is always a number.
function createUser(input) {
  if (input === null || typeof input !== 'object') {
    throw new ValidationError('input must be an object');
  }
  const { name } = input;
  if (typeof name !== 'string' || name.trim() === '') {
    throw new ValidationError('name must be a non-empty string');
  }

  let age = input.age;
  if (typeof age === 'string') {
    if (!/^\d+$/.test(age.trim())) throw new ValidationError('age must be a whole number');
    age = Number(age.trim());
  }
  if (typeof age !== 'number' || !Number.isInteger(age) || age < 0 || age > 150) {
    throw new ValidationError('age must be a whole number from 0 to 150');
  }

  return { name, age };
}

module.exports = { createUser, ValidationError };
EOF
cat >> test/users.test.js <<'EOF'

const { ValidationError } = require('../users');
const bad = (input) => assert.throws(() => createUser(input), ValidationError);

test('coerces numeric string age', () => {
  assert.deepStrictEqual(createUser({ name: 'A', age: '42' }), { name: 'A', age: 42 });
  assert.strictEqual(createUser({ name: 'A', age: 0 }).age, 0);
  assert.strictEqual(createUser({ name: 'A', age: '150' }).age, 150);
});

test('rejects bad names', () => {
  [undefined, null, 5, '', '   '].forEach((name) => bad({ name, age: 20 }));
});

test('rejects bad ages', () => {
  [undefined, null, '', ' ', 'abc', '4.5', '-1', 1.5, -1, 151, '151', NaN, Infinity, true, [], '1e2']
    .forEach((age) => bad({ name: 'A', age }));
});

test('rejects non-object input', () => {
  [null, undefined, 'x'].forEach(bad);
});
EOF
